// Parity check of the image preprocessing layer (src/image/preprocess.ts) against the Python source
// of truth.
//
// The fixture `image-preprocess/parity.json` is generated by the recipe
// (tools/export-recipes/siglip2/preprocess.py). The source of truth is transformers 5.14.1's
// `SiglipImageProcessor` (`TorchvisionBackend` — the fast side v5's `AutoImageProcessor` returns by
// default), and it holds, for 7 cases:
//  - `input`       the synthetic image's RGB8 (row-major, 3 bytes per pixel)
//  - `resized`     the RGB8 right after resize. That it is **exactly the full pipeline's
//                  intermediate** was measured at emit time (passed through the fused
//                  normalization it is bit-identical to `pixelValues`)
//  - `pixelValues` the normalized `[3, outHeight, outWidth]` f32
//
// It depends on neither real assets (under outputs/) nor a GPU, so it always runs.
//
// What is pinned is behaviour: "the same RGB8 in gives the same `pixel_values` as Python". How the
// weights are held or how the 2 passes are run is not pinned.
//
// ## Deriving the tolerance (measured)
//
// resize is **not an exact match** — the reference accumulates in f32 and this side in f64, so
// only the samples that land on a rounding boundary shift by 1 LSB (an isolation that moved one
// axis at a time measured the difference from the reference's f32 path **before** rounding at
// around 1e-4 to 2.4e-3). Measured:
//
//  - the difference is **always within 1 LSB** (13 geometries × 2 kinds of image = 1,286,856
//    samples, maximum 1)
//  - 0.28% of the samples shift (same set). In this fixture's 7 cases, 7 of 3,063 samples = 0.23%
//  - half-up rounding is correct. In the same measurement half-down increases the mismatches 3.1×
//    and half-even 2.0×, and both worsen to a maximum of 2 LSB (do not be misled by ties in the
//    fixture that happen to look like half-down)
//
// So the check is split into 3 tiers:
//  ① normalization alone is an **exact match** (the f32 made from the reference `resized` is
//    bit-identical to `pixelValues`)
//  ② resize is within 1 LSB + a cap on the mismatch rate ({@link MISMATCH_RATE_CAP} against the
//    measured 0.23%)
//  ③ the full path is ② carried into f32 = {@link PIXEL_ATOL}
//
// ① and ② are separate because with only a full-path comparison under a tolerance, a mixed-up
// normalization constant (some combinations give a difference smaller than 1 LSB) slips through.
//
// ## Handling bicubic (`resample: 3`)
//
// The fixture's source of truth is SigLIP2 = **bilinear**, so the comparison of the bicubic branch
// against the Python source of truth is not here (the measurement belongs to Depth Anything V2's
// real-image parity check = `e2e_depth_anything_real_test.ts` — on every run in an environment with
// the assets, it measures that the `pixel_values` of a 1024² real image shrunk to 518² match
// `DPTImageProcessor` **within 1 LSB / 0.5% mismatch rate**). What this file covers is only the
// asset-free **kernel signatures**: identity at identical sizes (the support radius of 2 is built
// correctly), and an **overshoot beyond the input's value range** at a step edge (which only a
// cubic kernel with a negative lobe produces).

import { readTextFile } from "@karume/test-support/fs";
import { assert, assertAlmostEquals, assertEquals, assertThrows } from "@std/assert";
import { describe, it, test } from "vite-plus/test";
import { ModelInputError } from "../src/errors.ts";
import {
  normalizationOverflow,
  normalizeToNchw,
  resizePlaneF32,
  resizeRgb8,
  type Rgb8Image,
} from "../src/image/preprocess.ts";

type Case = {
  readonly name: string;
  readonly why: string;
  readonly height: number;
  readonly width: number;
  readonly outHeight: number;
  readonly outWidth: number;
  readonly input: number[];
  readonly resized: number[];
  readonly pixelValues: number[];
};

type Fixture = {
  readonly constants: {
    readonly imageMean: [number, number, number];
    readonly imageStd: [number, number, number];
    readonly rescaleFactor: number;
  };
  readonly checkpoints: Record<string, { readonly height: number; readonly width: number }>;
  readonly cases: Case[];
};

const FIXTURE_PATH = new URL("./fixtures/image-preprocess/parity.json", import.meta.url);
const fixture = JSON.parse(await readTextFile(FIXTURE_PATH)) as Fixture;

const { imageMean, imageStd } = fixture.constants;

/** The tolerance per resize sample (1 LSB of uint8). Derived at the top of the file. */
const RESIZE_MAX_DELTA = 1;

/** The cap on the share of mismatched samples. More than 4× the measured 0.23%. */
const MISMATCH_RATE_CAP = 0.01;

/**
 * The full-path tolerance. 1 LSB of uint8 is `1 / 127.5 = 7.8431e-3` after normalization; with the
 * rounding into f32 on top, the measured maximum is 7.84314e-3. This value adds a small margin.
 */
const PIXEL_ATOL = 7.85e-3;

const imageOf = (testCase: Case): Rgb8Image => ({
  data: Uint8Array.from(testCase.input),
  width: testCase.width,
  height: testCase.height,
});

const resizedOf = (testCase: Case): Rgb8Image => ({
  data: Uint8Array.from(testCase.resized),
  width: testCase.outWidth,
  height: testCase.outHeight,
});

// ---- The fixture itself -------------------------------------------------------

test("the fixture is not empty (a mix-up has not let every case through)", () => {
  // Placed first. If a misread or a failed generation empties the cases, the later loops run 0
  // times and "green but checking nothing" silently holds.
  assertEquals(fixture.cases.length, 7);
  assertEquals(imageMean, [0.5, 0.5, 0.5]);
  assertEquals(imageStd, [0.5, 0.5, 0.5]);
  assertEquals(fixture.constants.rescaleFactor, 1 / 255);
  // The preprocessing constants are shared by both the 224 and 384 checkpoints (that only size
  // differs was measured at emit time). A fixture with only one was made without that claim being
  // checked.
  assert(Object.keys(fixture.checkpoints).length >= 2, "only one checkpoint");
  for (const testCase of fixture.cases) {
    assertEquals(
      testCase.input.length,
      testCase.width * testCase.height * 3,
      `[${testCase.name}] length of input`,
    );
    assertEquals(
      testCase.resized.length,
      testCase.outWidth * testCase.outHeight * 3,
      `[${testCase.name}] length of resized`,
    );
    assertEquals(
      testCase.pixelValues.length,
      testCase.resized.length,
      `[${testCase.name}] length of pixelValues`,
    );
  }
});

// ---- ① Normalization (separated from resize and pinned by exact match) --------------------------

for (const testCase of fixture.cases) {
  test(`normalization parity [${testCase.name}] reference resized → pixelValues is bit-identical`, () => {
    const got = normalizeToNchw(resizedOf(testCase), imageMean, imageStd);
    assertEquals(Array.from(got), testCase.pixelValues);
  });
}

// ---- ② resize (within 1 LSB) --------------------------------------------------

for (const testCase of fixture.cases) {
  test(`resize parity [${testCase.name}] ${testCase.why}`, () => {
    const got = resizeRgb8(imageOf(testCase), testCase.outWidth, testCase.outHeight);
    assertEquals(got.width, testCase.outWidth);
    assertEquals(got.height, testCase.outHeight);
    for (let index = 0; index < testCase.resized.length; index += 1) {
      const delta = Math.abs(got.data[index] - testCase.resized[index]);
      assert(
        delta <= RESIZE_MAX_DELTA,
        `sample ${index} is ${got.data[index]} (reference ${testCase.resized[index]})`,
      );
    }
  });
}

test("the resize mismatch rate stays within the measured range (all cases combined)", () => {
  // With only the cap of 1 LSB, an implementation that shifts every pixel by 1 (e.g. mixed-up
  // rounding) would pass.
  let mismatched = 0;
  let total = 0;
  for (const testCase of fixture.cases) {
    const got = resizeRgb8(imageOf(testCase), testCase.outWidth, testCase.outHeight);
    for (let index = 0; index < testCase.resized.length; index += 1) {
      if (got.data[index] !== testCase.resized[index]) mismatched += 1;
    }
    total += testCase.resized.length;
  }
  const rate = mismatched / total;
  assert(
    rate <= MISMATCH_RATE_CAP,
    `mismatch rate ${rate} (${mismatched}/${total}) exceeded the cap`,
  );
});

// ---- ③ Full path (RGB8 → pixel_values) ----------------------------------------

for (const testCase of fixture.cases) {
  test(`full-path parity [${testCase.name}] ${testCase.why}`, () => {
    const resized = resizeRgb8(imageOf(testCase), testCase.outWidth, testCase.outHeight);
    const got = normalizeToNchw(resized, imageMean, imageStd);
    assertEquals(got.length, testCase.pixelValues.length);
    for (let index = 0; index < got.length; index += 1) {
      assertAlmostEquals(got[index], testCase.pixelValues[index], PIXEL_ATOL, `sample ${index}`);
    }
  });
}

// ---- Kernel signatures of bicubic (DA-V2's `resample: 3`) ------------------------

test("bicubic is the identity at the same size (the support radius of 2 is built correctly)", () => {
  // At scale 1 the cubic kernel reduces to `[…, 0, 1, 0, …]` at integer positions. Leaving the
  // support radius at 1 (bilinear's value) or mixing up the kernel's branch boundaries blurs the
  // high-frequency image here.
  for (const testCase of fixture.cases) {
    const image = imageOf(testCase);
    const got = resizeRgb8(image, testCase.width, testCase.height, "bicubic");
    assertEquals(Array.from(got.data), Array.from(image.data), `[${testCase.name}]`);
  }
});

test("bicubic goes beyond the input's value range at a step edge (bilinear does not)", () => {
  // The direct signature of the negative lobe. If the filter choice is silently ignored and it
  // falls back to bilinear, the overshoot disappears and this fails (the identity check alone
  // cannot tell the 2 filters apart).
  const low = 40;
  const high = 200;
  const width = 8;
  const data = new Uint8Array(width * 3);
  for (let x = 0; x < width; x += 1) {
    const value = x < width / 2 ? low : high;
    data[x * 3] = value;
    data[x * 3 + 1] = value;
    data[x * 3 + 2] = value;
  }
  const step: Rgb8Image = { data, width, height: 1 };

  const bicubic = resizeRgb8(step, width * 4, 1, "bicubic");
  const bilinear = resizeRgb8(step, width * 4, 1, "bilinear");

  assert(Math.min(...bicubic.data) < low, "bicubic has no undershoot");
  assert(Math.max(...bicubic.data) > high, "bicubic has no overshoot");
  assertEquals(Math.min(...bilinear.data), low, "bilinear went below the value range");
  assertEquals(Math.max(...bilinear.data), high, "bilinear went above the value range");
});

test("bicubic's overshoot saturates instead of wrapping around", () => {
  // MUST: assigning into a `Uint8Array` wraps out-of-range values mod 256 (a black/white inversion
  // passes silently). The edge values are driven past the limits to see directly that they stick to
  // the saturated side.
  const width = 8;
  const data = new Uint8Array(width * 3);
  for (let x = 0; x < width; x += 1) {
    const value = x < width / 2 ? 0 : 255;
    data[x * 3] = value;
    data[x * 3 + 1] = value;
    data[x * 3 + 2] = value;
  }
  const got = resizeRgb8({ data, width, height: 1 }, width * 4, 1, "bicubic");

  assertEquals(Math.min(...got.data), 0);
  assertEquals(Math.max(...got.data), 255);
});

test("bicubic downscaling stretches the support by the scale (exactly DA-V2's real use; taps checked by hand)", () => {
  // There are 3 other asset-free bicubic cases, but all are on the `filterScale === 1` side
  // (identity and upscaling), so the `filterScale = max(scale, 1) > 1` branch of `buildTaps` =
  // **downscaling** is never exercised. The comparison against the Python source of truth exists
  // only in the real-asset e2e, so this places expected values from Pillow's `ImagingResample`
  // formula expanded by hand.
  //
  // Geometry: 4 → 2 (`scale = 2` / `filterScale = 2` / `support = 2×2 = 4`). The input is one row
  // of 4 pixels `[0, 0, 0, 255]` (an asymmetric shape where only the last point is set — the value
  // moves if the order of the weights is swapped left to right).
  //
  // The raw weights of output 1 (`center = 1.5×2 = 3.0`, `start = 0` / `stop = 4`) are
  // `cubic((j − 2.5) / 2)` = [cubic(−1.25), cubic(−0.75), cubic(−0.25), cubic(0.25)]
  //   = [−0.0703125, 0.2265625, 0.8671875, 0.8671875] (sum 1.890625).
  // Only j = 3 is set, so 255 × 0.8671875 / 1.890625 = 116.9628… → rounded to **117**.
  //
  // Output 0 (`center = 1.0`, `start = 0` / `stop = 4`) has the weights in mirrored order, and the
  // weight of the set j = 3 is the negative lobe (−0.0703125 / 1.890625). 255 × that = −9.48…, and
  // `round8`'s clamp saturates it to **0**.
  //
  // The changes this should catch: dropping `filterScale` from `support` (→ output 1 is 113) /
  // dropping `/ filterScale` from `weight`'s argument (→ 135). Both stay green with the existing 3
  // cases.
  const data = new Uint8Array([0, 0, 0, 0, 0, 0, 0, 0, 0, 255, 255, 255]);
  const image: Rgb8Image = { data, width: 4, height: 1 };

  const got = resizeRgb8(image, 2, 1, "bicubic");
  assertEquals(Array.from(got.data), [0, 0, 0, 117, 117, 117]);

  // The control — the same geometry through bilinear gives another value (the filter choice is not
  // silently ignored).
  const bilinear = resizeRgb8(image, 2, 1, "bilinear");
  assertEquals(Array.from(bilinear.data), [0, 0, 0, 109, 109, 109]);
});

// ---- The entry contract (anything unexpected fails loudly) --------------------------------------

test("fails when the pixel array's length does not match the size", () => {
  const image: Rgb8Image = { data: new Uint8Array(11), width: 2, height: 2 };
  assertThrows(() => resizeRgb8(image, 4, 4), ModelInputError, "RGB8 length 11");
  assertThrows(
    () => normalizeToNchw(image, imageMean, imageStd),
    ModelInputError,
    "RGB8 length 11",
  );
});

test("fails when a dimension is not a positive integer", () => {
  const empty: Rgb8Image = { data: new Uint8Array(0), width: 0, height: 3 };
  assertThrows(() => resizeRgb8(empty, 4, 4), ModelInputError, "Image size 0×3");
  const image: Rgb8Image = { data: new Uint8Array(12), width: 2, height: 2 };
  assertThrows(() => resizeRgb8(image, 0, 4), ModelInputError, "Output size 0×4");
  assertThrows(() => resizeRgb8(image, 4, 2.5), ModelInputError, "Output size 4×2.5");
});

test("an unknown filter name fails (an Object.prototype member is not taken as the kernel, giving all black)", () => {
  // The type `ResampleFilter` closes it, but that does not reach callers that drive the barrel from
  // JS.
  const image: Rgb8Image = { data: new Uint8Array(12).fill(200), width: 2, height: 2 };
  for (const filter of ["toString", "constructor", "__proto__", "lanczos"]) {
    const error = assertThrows(
      () => resizeRgb8(image, 4, 4, filter as never),
      Error,
      `interpolation filter ${JSON.stringify(filter)} is not supported`,
    );
    // A misspelled name is not a value-range violation of the input (ADR 0107 decision 3 — the same
    // treatment as sampler names).
    assert(!(error instanceof ModelInputError), `${filter} became a ModelInputError`);
  }
});

test("fails when mean / std cannot be used for normalization (no plane of Inf / NaN is returned silently)", () => {
  const image: Rgb8Image = { data: new Uint8Array(12).fill(128), width: 2, height: 2 };
  for (const bad of [0, -0.5, Number.NaN, Number.POSITIVE_INFINITY]) {
    assertThrows(
      () => normalizeToNchw(image, imageMean, [imageStd[0], bad, imageStd[2]]),
      ModelInputError,
      `std[1] = ${bad} is not a positive finite number`,
    );
  }
  for (const bad of [Number.NaN, Number.NEGATIVE_INFINITY]) {
    assertThrows(
      () => normalizeToNchw(image, [imageMean[0], imageMean[1], bad], imageStd),
      ModelInputError,
      `mean[2] = ${bad} is not finite`,
    );
  }
});

test("fails on finite mean / std whose normalization overflows f32 (no Inf / NaN in the tails is returned silently)", () => {
  const image: Rgb8Image = { data: new Uint8Array(12).fill(128), width: 2, height: 2 };
  const max = Number.MAX_VALUE;
  const cases: readonly [
    string,
    readonly [number, number, number],
    readonly [number, number, number],
  ][] = [
    // (128 − mean·255) / (std·255) is +Inf (dividing by a tiny std).
    ["tiny std", imageMean, [imageStd[0], Number.MIN_VALUE, imageStd[2]]],
    // mean·255 is Infinity in f64 (the offset is non-finite).
    ["huge mean", [imageMean[0], max, imageMean[2]], imageStd],
    // mean·255 / std·255 are both Infinity, and Inf / Inf = NaN.
    ["huge mean and std", [imageMean[0], max, imageMean[2]], [imageStd[0], max, imageStd[2]]],
    // Finite in f64 but overflowing when narrowed to f32 ((255 − 0) / (std·255) = 1e39).
    [
      "std overflowing only in f32",
      [0, imageMean[1], imageMean[2]],
      [1e-39, imageStd[1], imageStd[2]],
    ],
  ];
  for (const [label, mean, std] of cases) {
    assertThrows(
      () => normalizeToNchw(image, mean, std),
      ModelInputError,
      "is not finite in f32",
      label,
    );
  }
});

test("fails on a mean / std pair that is finite one by one but overflows f32 after normalization", () => {
  // The quotient is finite in f64 but becomes ±Inf once put into a Float32Array, and the whole
  // plane goes to the GPU.
  const image: Rgb8Image = { data: new Uint8Array(12).fill(128), width: 2, height: 2 };
  assertThrows(
    () => normalizeToNchw(image, imageMean, [imageStd[0], 1e-50, imageStd[2]]),
    ModelInputError,
    "channel 1: the normalized range",
  );
  assertThrows(
    () => normalizeToNchw(image, [1e40, imageMean[1], imageMean[2]], imageStd),
    ModelInputError,
    "is not finite in f32",
  );
  // The decision is made by the two ends of the pixel range, so it does not depend on the pixel
  // values (it fails even with every pixel 128 = it does not scan).
  assertEquals(normalizationOverflow(imageMean, imageStd), undefined);
  // Boundary: a std where 255 / (std·255) is just below f32's maximum passes.
  const tiny = 1 / 3.4e38;
  assertEquals(normalizationOverflow([0, 0, 0], [tiny, tiny, tiny]), undefined);
});

// ---- Whether a failure is caused by the input (ADR 0107) ------------------------------------

describe("when the host sorts failures of the shared image layer into 400 / 500", () => {
  const image: Rgb8Image = { data: new Uint8Array(12), width: 2, height: 2 };

  it("a size violation of the image the caller passed is caught as ModelInputError", () => {
    const broken: Rgb8Image = { data: new Uint8Array(0), width: 0, height: 3 };
    assertThrows(() => resizeRgb8(broken, 4, 4), ModelInputError);
    assertThrows(() => normalizeToNchw(broken, imageMean, imageStd), ModelInputError);
  });

  it("a length violation of the pixel array the caller passed is caught as ModelInputError", () => {
    const short: Rgb8Image = { data: new Uint8Array(11), width: 2, height: 2 };
    assertThrows(() => resizeRgb8(short, 4, 4), ModelInputError);
  });

  it("a violation of the output size the caller specified is also caught as ModelInputError", () => {
    // The 3 families pass only `config.imageWidth` / `imageHeight` (parsed positive integers), so
    // the callers of this path are only those driving `resizeRgb8` from the barrel directly = the
    // size is the caller's request.
    assertThrows(() => resizeRgb8(image, 0, 4), ModelInputError);
  });

  it("the preconditions of the internal helper resizePlaneF32 are **not** ModelInputError", () => {
    // It is not on the public surface, and its only callers are inside the birefnet /
    // depth-anything pipelines. What breaks is wiring, not the caller's input, so it stays a plain
    // Error / RangeError, the 500 kind.
    const lengthMismatch = assertThrows(() => resizePlaneF32(new Float32Array(5), 3, 2, 3, 2));
    assert(lengthMismatch instanceof Error);
    assert(
      !(lengthMismatch instanceof ModelInputError),
      "a plane length violation became a ModelInputError",
    );
    const badSize = assertThrows(() => resizePlaneF32(new Float32Array(6), 3, 2, 0, 2));
    assert(
      !(badSize instanceof ModelInputError),
      "an output width violation became a ModelInputError",
    );
  });
});
